<script setup lang="ts">import{computed}from'vue';import type{ServiceDistributionItem}from '@/types/dashboard';const props=defineProps<{items:ServiceDistributionItem[];loading:boolean}>();const colors=['#2563EB','#16A34A','#F59E0B','#8B5CF6','#64748B'];const gradient=computed(()=>{let from=0;return `conic-gradient(${props.items.map((i,n)=>{const to=from+i.percentage;const s=`${colors[n%colors.length]} ${from}% ${to}%`;from=to;return s}).join(',')})`});const total=computed(()=>props.items.reduce((s,i)=>s+i.households,0));const money=(v:number)=>new Intl.NumberFormat('vi-VN',{notation:'compact',maximumFractionDigits:1}).format(v)</script>
<template><v-card class="pa-4 pa-md-5 h-100" border rounded="xl"><div class="text-h6 font-weight-bold">Cơ cấu dịch vụ</div><div class="text-caption text-medium-emphasis mb-4">Số hộ, tỷ trọng và doanh thu theo dịch vụ</div><v-skeleton-loader v-if="loading" type="image,list-item-three-line" /><div v-else-if="!items.length" class="empty-state">Chưa có dữ liệu dịch vụ</div><div v-else class="service-layout"><div class="service-donut" :style="{background:gradient}"><div><strong>{{ total }}</strong><span>hộ dân</span></div></div><div class="service-legend"><div v-for="(item,index) in items" :key="item.service_id" class="service-legend__item"><i :style="{background:colors[index%colors.length]}" /><div class="flex-grow-1 min-width-0"><div class="d-flex justify-space-between ga-2"><span class="text-truncate">{{ item.name }}</span><strong>{{ item.percentage }}%</strong></div><div class="text-caption text-medium-emphasis">{{ item.households }} hộ · {{ money(item.revenue) }} ₫</div></div></div></div></div></v-card></template>
